"""Typed access to the stored resume data (generated by `process-resumes`) and your curation.

Library module: paths, record types and loaders shared by process_resumes.py, query_resume.py and
build_resume.py. Standard library only.
"""
from __future__ import annotations

from collections.abc import Iterable, Mapping
from pathlib import Path
from typing import Any, Final, NotRequired, TypedDict, cast

from jk import common
from jk.resumes import tables

TEXT_DIR: Final[Path] = common.output_dir()
MISSING_DATA: Final[str] = "No resume data yet: run `process-resumes` first."


# Themes the tools act on (lead questions, typical questions, JD matching) and the summary angles `for-jd` ranks by.
# `tests/resumes/test_curate.py` keeps these equal to the tables that use them.
KNOWN_THEMES: Final[tuple[str, ...]] = (
    "topic-01", "topic-02", "topic-03", "topic-04", "topic-05", "budget-financial",
    "topic-06", "topic-07", "delivery-leadership", "topic-08", "executive-advisory", "topic-09",
    "topic-10", "topic-12", "topic-11", "governance-compliance", "topic-13", "mentoring",
    "topic-14", "topic-15", "topic-16", "topic-17", "topic-18", "topic-19", "topic-20",
    "stakeholder-alignment", "strategy-roadmap", "team-leadership", "vendor-management", "workshops",
)
SUMMARY_ANGLES: Final[tuple[str, ...]] = (
    "focus-1", "focus-2", "focus-3", "focus-4", "topic-17",
)
LINE_LIMIT: Final[int] = 200        # most characters in one resume line (an experience line)
LINE_WARN: Final[int] = 250         # beyond this a line is far over the limit and is flagged as such
SUMMARY_LIMIT: Final[int] = 400     # most characters in the summary: two lines


class Bullet(TypedDict):
    """One experience bullet, deduplicated across resumes."""

    id: str
    text: str
    role_start: str | None
    skills: list[str]
    skills_manual: NotRequired[list[str]]
    themes: list[str]
    metrics: list[str]
    sources: list[str]
    variants: NotRequired[list[str]]
    wordings: NotRequired[dict[str, list[str]]]
    needs_review: NotRequired[bool]
    ignored: NotRequired[bool]


class Role(TypedDict):
    """One period at a company (start/end as YYYY-MM, or YYYY when a resume gives only a year; end None = current)."""

    start: str | None
    end: str | None
    titles: list[str]
    subtitles: list[str]
    clients: list[str]
    sources: list[str]
    ends: NotRequired[dict[str, str | None]]
    field_sources: NotRequired[dict[str, dict[str, list[str]]]]


class Company(TypedDict):
    """One employer with its roles and bullets."""

    id: str
    name: str
    aliases: list[str]
    roles: list[Role]
    bullets: list[Bullet]


class SkillEntry(TypedDict):
    """A skill with its alternative spellings and the resumes that list it."""

    name: str
    aliases: list[str]
    sources: list[str]


class Skills(TypedDict):
    """The skills vocabulary."""

    groups: dict[str, list[SkillEntry]]
    tag_only: NotRequired[list[str]]


class Summary(TypedDict):
    """One opening summary paragraph."""

    id: str
    text: str
    angles: list[str]
    sources: list[str]


class ItemSource(TypedDict):
    """The resume files that state one profile item (a headline, a certification ...)."""

    section: str
    text: str
    sources: list[str]


class ResumeProfile(TypedDict):
    """The resume profile sections (contain no contact details)."""

    summaries: list[Summary]
    headlines: NotRequired[list[str]]
    profile_points: list[str]
    education: list[str]
    certifications: list[Any]
    projects: list[str]
    item_sources: NotRequired[list[ItemSource]]


class ResumeData(TypedDict):
    """Everything the merge step works on."""

    companies: dict[str, Company]
    skills: Skills
    profile: ResumeProfile


def empty_profile() -> ResumeProfile:
    """A profile with every list present and empty."""
    return {"summaries": [], "profile_points": [], "education": [], "certifications": [], "projects": [],
            "item_sources": []}


def load_companies() -> dict[str, Company]:
    """{company id: company} with roles and bullets."""
    return cast(dict[str, Company], tables.load_companies())


def load_skills() -> Skills:
    """The skills vocabulary."""
    return cast(Skills, tables.load_skills() or {"groups": {}})


def load_profile() -> ResumeProfile:
    """Summaries, headlines, certifications and education."""
    return cast(ResumeProfile, tables.load_profile() or empty_profile())


def load_ledger() -> dict[str, dict[str, Any]]:
    """Which resume files were processed, with their size/mtime/hash."""
    return tables.load_ledger()


def load_curated() -> dict[str, Any]:
    """The user's curation (certifications, skill rules, known-wrong figures ...) that survives rebuilds, or {}."""
    return tables.load_curation("curated") or {}


def load_themes_file() -> dict[str, Any]:
    """The user's bullet themes, ignored fragments and summary angles, or empty ones."""
    return tables.load_curation("themes") or {"themes": {}, "ignore": [], "summary_angles": {}}


def orphan_curation(companies: Mapping[str, Company], profile: ResumeProfile, themes: Mapping[str, Any],
                    curated: Mapping[str, Any] | None = None) -> list[str]:
    """Ids in the curation (themes, ignore, summary_angles, and the approved short wordings in `curated`) that
    match no current bullet or summary. A bullet id is a hash of its text, so editing a resume can leave hand
    curation pointing at nothing."""
    bullets = {b["id"] for c in companies.values() for b in c["bullets"]}
    summaries = {s["id"] for s in profile.get("summaries", [])}
    orphans = [f"theme {i}" for i in themes.get("themes", {}) if i not in bullets]
    orphans += [f"ignore {i}" for i in themes.get("ignore", []) if i not in bullets]
    orphans += [f"summary angle {i}" for i in themes.get("summary_angles", {}) if i not in summaries]
    orphans += [f"short wording {i}" for i in (curated or {}).get("short_wording", {}) if i not in bullets]
    return sorted(orphans)


def newest_start(company: Company) -> str:
    """Start date of the company's most recent role ('' when unknown)."""
    return max((role["start"] or "") for role in company["roles"])


def newest_first(companies: Iterable[Company]) -> list[Company]:
    """Companies ordered by their most recent role, newest first."""
    return sorted(companies, key=newest_start, reverse=True)
